import presentation.support.*

fun AgendaBuilder.lightningTalk(title: String, speaker: String) {
  session(title) {
    this.speaker = speaker
    minutes = 5
  }
}

val program = agenda("Lightning talks") {
  lightningTalk("Receivers", "Ada")
}
